  function matchScore(report,activity){if(!activity)return 0;var explicit=(report.activityId||'').toLowerCase();if(explicit&&explicit===activity.id.toLowerCase())return .99;var text=normalize(report.text+' '+(report.discipline||'')+' '+(report.location||''));if(text.indexOf(activity.id.toLowerCase())>=0)return .99;var qt=tokenSet(text);var at=tokenSet(normalize(activity.name+' '+activity.discipline+' '+activity.location+' '+activity.id));var overlap=0;at.forEach(function(t){if(qt.has(t))overlap++;});var base=at.size?overlap/at.size:0;var query=qt.size?overlap/Math.min(qt.size,at.size||1):0;var score=base*.65+query*.35;if(report.discipline&&report.discipline.toLowerCase()===activity.discipline.toLowerCase())score+=.09;if(report.location&&normalize(report.location).split(' ').some(function(t){return tokenSet(normalize(activity.location)).has(t);}))score+=.1;return Math.min(.96,score);}
  function normalize(s){var synonyms={erected:'erect',erecting:'erect',erection:'erect',installed:'install',installing:'install',installation:'install',calibration:'calibrate',calibrated:'calibrate',started:'start',began:'start',completed:'complete',finished:'complete',finishing:'complete',spools:'spool',foundations:'foundation',transmitters:'transmitter',trays:'tray',aligning:'align',aligned:'align',backfilled:'backfill',backfilling:'backfill',inspection:'inspect',inspected:'inspect'};return String(s||'').toLowerCase().replace(/[^a-z0-9\-\s]/g,' ').replace(/[-_]/g,' ').split(/\s+/).filter(Boolean).map(function(t){return synonyms[t]||t;}).join(' ');}
  function tokenSet(s){var stop=new Set(['the','a','an','and','or','in','on','at','to','of','is','are','was','were','today','team','crew','activity','work','complete','completed','finished','with','for','from','by','this','that','after','before','around','percent','unit','phase','continue','continues','today']);var set=new Set();normalize(s).split(' ').forEach(function(t){if(t.length>1&&!stop.has(t))set.add(t);});return set;}
  function candidates(report){var analysis=(state.intelligence&&state.intelligence.matches&&state.intelligence.matches[report.id])||report.analysis;if(analysis&&analysis.candidates){return analysis.candidates.map(function(item){return{activity:currentActivity(item.activity_id),score:Number(item.score)||0,reasons:item.reasons||[]};}).filter(function(item){return !!item.activity;}).slice(0,3);}return state.activities.map(function(a){return{activity:a,score:matchScore(report,a),reasons:['Legacy local text match']};}).sort(function(a,b){return b.score-a.score;}).slice(0,3);}
  function suggestedActivity(report){if(report.activityId){var exact=currentActivity(report.activityId);if(exact)return exact;}var list=candidates(report);return list.length&&list[0].score>=.70?list[0].activity:null;}
  function scoreLabel(score){return Math.round(score*100)+'%';}
  function scoreClass(score){return score>=.72?'':score>=.46?'medium':'low';}
  function scorePill(score){var cls=score>=.72?'pill-green':score>=.46?'pill-amber':'pill-red';return'<span class="match-pill '+cls+'">'+scoreLabel(score)+' match</span>';}
  function addAudit(actor,action,record,detail){var d=new Date();var stamp=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')+' '+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');state.audit.unshift({time:stamp,actor:actor||'Project Planner',action:action,record:record,detail:detail||''});if(state.audit.length>250)state.audit=state.audit.slice(0,250);}
  function toast(message,type){var root=document.getElementById('toastRoot');var node=document.createElement('div');node.className='toast'+(type==='error'?' error':'');node.innerHTML='<span class="toast-dot"></span><span>'+esc(message)+'</span>';root.appendChild(node);setTimeout(function(){node.style.opacity='0';node.style.transform='translateY(5px)';setTimeout(function(){node.remove();},220);},3400);}

  var VIEW_META={
    overview:{eyebrow:'PROJECT CONTROL CENTER · PHASE 02',title:'Project control center.',description:'One view of what was planned, what happened on site, and what needs a decision.'},
    schedule:{eyebrow:'PLANNING TO EXECUTION · ACTIVITY REGISTER',title:'Activity register',description:'Review L5/L6 work items alongside the latest actual progress captured from site.'},
    inbox:{eyebrow:'SITE UPDATES · PLANNER REVIEW',title:'Report inbox',description:'Turn unstructured updates into trusted, schedule-linked progress records.'},
    insights:{eyebrow:'EXECUTION LEARNING · PROJECT INSIGHTS',title:'Progress insights',description:'See where actual progress is moving and preserve patterns for future planning.'},
    audit:{eyebrow:'DATA GOVERNANCE · CHANGE HISTORY',title:'Audit trail',description:'See who changed each record, when, from which source, what changed, and why.'},
    users:{eyebrow:'ACCESS CONTROL · WORKSPACE ADMINISTRATION',title:'Users & roles',description:'Create workspace accounts and assign the least access each teammate needs.'},
    agent:{eyebrow:'FIELD CAPTURE · SUPERVISOR TIME AGENT',title:'AI Time Agent',description:'Describe what happened in ordinary language. Review the extracted facts and ranked schedule links before saving.'},
    conflicts:{eyebrow:'DATA QUALITY · SOURCE RECONCILIATION',title:'Conflict center',description:'Find different reports that disagree about the same activity and date; keep planner resolution explicit.'},
    missing:{eyebrow:'DATA COMPLETENESS · UPDATE CADENCE',title:'Missing progress updates',description:'Spot active scheduled activities without a linked update inside their expected reporting window.'},
    memory:{eyebrow:'EXECUTION INTELLIGENCE · HISTORICAL MEMORY',title:'Execution memory',description:'Inspect completed activity fingerprints, reported blockers, schedule links, and small-sample historical observations.'}
  };
  function render(){if(!authUser)return;var meta=VIEW_META[currentView]||VIEW_META.overview;document.getElementById('pageEyebrow').innerHTML=esc(meta.eyebrow).replace('·','<span class="eyebrow-line"></span>');document.getElementById('pageTitle').textContent=meta.title;document.getElementById('pageDescription').textContent=meta.description;document.getElementById('todayDate').textContent=new Date().toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'});document.getElementById('navTaskCount').textContent=state.activities.length;document.getElementById('navInboxCount').textContent=pendingReports().length;document.getElementById('navConflictCount').textContent=(state.intelligence&&state.intelligence.conflicts||[]).filter(function(c){return c.unresolved;}).length;document.getElementById('navMissingCount').textContent=(state.intelligence&&state.intelligence.missing_updates||[]).length;document.getElementById('usersNav').classList.toggle('hidden',authUser.role!=='Admin');document.getElementById('logUpdateButton').classList.toggle('hidden',!canImport());document.querySelectorAll('.nav-item').forEach(function(n){n.classList.toggle('active',n.getAttribute('data-view')===currentView);});var activeNavItem=document.querySelector('.nav-item.active'),activeNavGroup=activeNavItem&&activeNavItem.closest('.nav-group');if(activeNavGroup)activeNavGroup.open=true;var root=document.getElementById('viewRoot');if(currentView==='overview')root.innerHTML=renderOverview();else if(currentView==='schedule')root.innerHTML=renderSchedule();else if(currentView==='inbox')root.innerHTML=renderInbox();else if(currentView==='agent')root.innerHTML=renderAgent();else if(currentView==='conflicts')root.innerHTML=renderConflicts();else if(currentView==='missing')root.innerHTML=renderMissing();else if(currentView==='memory')root.innerHTML=renderMemory();else if(currentView==='insights')root.innerHTML=renderInsights();else if(currentView==='users')root.innerHTML=renderUsers();else root.innerHTML=renderAudit();bindViewEvents();}
  function renderOverview(){var total=state.activities.length;var avg=Math.round(state.activities.reduce(function(s,a){return s+(Number(a.progress)||0);},0)/Math.max(total,1));var waiting=pendingReports().length;var late=state.activities.filter(function(a){return new Date(a.plannedFinish+'T00:00:00')<new Date(todayISO()+'T00:00:00')&&Number(a.progress)<100;}).length;var approved=state.reports.filter(function(r){return r.status==='approved';}).length;var recent=state.reports.slice().sort(function(a,b){return (b.date||'').localeCompare(a.date||'');}).slice(0,4);var delayed=state.activities.filter(function(a){return new Date(a.plannedFinish+'T00:00:00')<new Date(todayISO()+'T00:00:00')&&Number(a.progress)<100;}).sort(function(a,b){return a.plannedFinish.localeCompare(b.plannedFinish);}).slice(0,3);var completed=state.activities.filter(function(a){return Number(a.progress)>=100;}).length;var inprog=state.activities.filter(function(a){return Number(a.progress)>0&&Number(a.progress)<100;}).length;var notstarted=total-completed-inprog;
    return'<div class="kpi-grid">'+kpiCard('Activities tracked',total,'L5/L6 schedule nodes','▤','', '8')+kpiCard('Actual progress',avg+'%','Across '+total+' registered activities','↗','green','Sample trend · illustrative')+kpiCard('Updates to review',waiting,'Across '+state.reports.length+' field reports','⇥','amber',waiting?'Planner action needed':'Inbox clear')+kpiCard('Activities overdue',late,'Past planned finish date','◷','blue',late?'Needs a schedule decision':'None overdue')+'</div>'+
    '<div class="dashboard-grid"><section class="panel"><div class="panel-header"><div class="panel-heading"><h2>Illustrative planned vs. actual trend</h2><p>Synthetic sample series · not a live historical forecast</p></div><div class="chart-legend"><span><i class="legend-dot"></i>Planned</span><span><i class="legend-dot teal"></i>Actual</span></div></div><div class="chart-body">'+chartSvg(avg)+'</div><div class="chart-caption"><span class="milestone-chip"><i></i>Illustrative trend only · current totals are shown in the activity register</span></div></section><section class="panel health-panel"><div class="panel-header"><div class="panel-heading"><h2>Execution snapshot</h2><p>Current activity health</p></div><button class="panel-action" data-nav="insights">View insights ↗</button></div><div class="panel-body"><div class="health-summary"><div class="health-ring"><strong>'+avg+'%</strong></div><div class="health-copy"><strong>Progress captured</strong><small>'+approved+' accepted field update'+(approved===1?'':'s')+' in this demo</small></div></div><div class="health-metrics"><div class="health-metric"><span class="metric-left"><i class="status-dot"></i>Complete</span><strong>'+completed+' activities</strong></div><div class="health-metric"><span class="metric-left"><i class="status-dot warn"></i>In progress</span><strong>'+inprog+' activities</strong></div><div class="health-metric"><span class="metric-left"><i class="status-dot gray"></i>Not started</span><strong>'+notstarted+' activities</strong></div></div><div class="health-divider"></div><div class="attention-card"><span class="attention-icon">◈</span><span><strong>'+waiting+' reports need a planner check.</strong> Review a match before it updates the register.</span></div></div></section></div>'+
    '<div class="lower-grid"><section class="panel"><div class="panel-header"><div class="panel-heading"><h2>Latest site updates</h2><p>Incoming reports with their suggested schedule links</p></div><button class="panel-action" data-nav="inbox">Open report inbox ↗</button></div>'+renderRecentTable(recent)+'</section><section class="panel"><div class="panel-header"><div class="panel-heading"><h2>Needs attention</h2><p>Activities beyond their planned finish</p></div><span class="match-pill '+(late?'pill-amber':'pill-green')+'">'+late+' items</span></div><div class="priority-list">'+(delayed.length?delayed.map(function(a){var days=Math.max(1,Math.ceil((new Date(todayISO())-new Date(a.plannedFinish+'T00:00:00'))/86400000));return'<div class="priority-item"><div class="priority-marker '+(days>3?'red':'')+'">!</div><div class="priority-content"><strong>'+esc(a.name)+'</strong><small>'+esc(a.id)+' · '+esc(a.discipline)+' · '+Number(a.progress)+'% complete</small></div><span class="priority-delta '+(days>3?'red':'')+'">+'+days+'d</span></div>';}).join(''):'<div class="empty-state"><strong>No overdue activities</strong>All open items are within planned dates.</div>')+'</div></section></div>';
  }
  function kpiCard(title,value,sub,icon,color,foot){return'<article class="kpi-card"><div class="kpi-head"><span>'+esc(title)+'</span><span class="kpi-icon '+esc(color||'')+'">'+icon+'</span></div><div class="kpi-value-row"><strong class="kpi-value">'+esc(value)+'</strong><span class="kpi-sub">'+esc(sub)+'</span></div><div class="kpi-foot"><span>'+esc(foot)+'</span><span>↗</span></div></article>';}
  function chartSvg(avg){var plan=[12,22,35,48,61,74,86];var actual=[9,18,29,42,53,61,Math.min(90,avg)];var x0=42,xStep=77,yTop=12,yBottom=165;function y(v){return yBottom-(v/100)*(yBottom-yTop);}function pts(arr){return arr.map(function(v,i){return(x0+i*xStep)+','+y(v).toFixed(1);}).join(' ');}var labels=['Sep 03','Sep 07','Sep 11','Sep 15','Sep 19','Sep 23','Sep 29'];var grid='';[0,25,50,75,100].forEach(function(v){grid+='<line class="chart-grid" x1="34" x2="522" y1="'+y(v)+'" y2="'+y(v)+'"></line><text class="chart-axis" x="4" y="'+(y(v)+3)+'">'+v+'%</text>';});var xlabels=labels.map(function(l,i){return'<text class="chart-axis" x="'+(x0+i*xStep)+'" y="184" text-anchor="middle">'+l+'</text>';}).join('');var area='34,'+yBottom+' '+pts(actual)+' '+(x0+(actual.length-1)*xStep)+','+yBottom;var point='<circle class="chart-point" cx="'+(x0+(actual.length-1)*xStep)+'" cy="'+y(actual[actual.length-1])+'" r="4"></circle>';return'<svg class="progress-chart" viewBox="0 0 548 194" role="img" aria-label="Planned and actual project progress trend"><defs><linearGradient id="actualFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#4cb194" stop-opacity=".18"></stop><stop offset="1" stop-color="#4cb194" stop-opacity="0"></stop></linearGradient></defs>'+grid+'<polygon class="chart-area" points="'+area+'"></polygon><polyline class="chart-plan" points="'+pts(plan)+'"></polyline><polyline class="chart-actual" points="'+pts(actual)+'"></polyline>'+point+xlabels+'</svg>';}
  function renderRecentTable(reports){if(!reports.length)return'<div class="empty-state"><strong>No field reports yet</strong>Import a report or log an update to get started.</div>';var rows=reports.map(function(r){var a=r.activityId?currentActivity(r.activityId):suggestedActivity(r);var score=a?matchScore(r,a):0;return'<tr><td><div class="task-cell"><span class="task-mini-icon">'+disciplineIcon(r.discipline)+'</span><span><strong>'+esc(r.source)+'</strong><small>'+esc(r.id)+' · '+esc(fmtDate(r.date,true))+'</small></span></div></td><td>'+esc(r.discipline||'—')+'</td><td>'+(a?'<span class="source-code">'+esc(a.id)+'</span>':'<span class="muted-text">No suggestion</span>')+'</td><td>'+scorePill(score)+'</td><td>'+statusPill(r.status)+'</td><td>'+(canReview()?'<button class="table-link" data-review="'+esc(r.id)+'">Review</button>':'')+'</td></tr>';}).join('');return'<div class="updates-table-wrap"><table class="updates-table"><thead><tr><th>Source</th><th>Discipline</th><th>Suggested link</th><th>Match</th><th>State</th><th></th></tr></thead><tbody>'+rows+'</tbody></table></div>';}

  function renderSchedule(){var rows=state.activities.filter(function(a){var f=scheduleFilter;var status=statusForActivity(a);var ok=f==='all'||(f==='open'&&status!=='Complete')||(f==='complete'&&status==='Complete')||(f==='late'&&new Date(a.plannedFinish+'T00:00:00')<new Date(todayISO()+'T00:00:00')&&Number(a.progress)<100)||(f.toLowerCase()===a.discipline.toLowerCase());var q=scheduleSearch.toLowerCase();var match=!q||(a.id+' '+a.name+' '+a.discipline+' '+a.location).toLowerCase().indexOf(q)>=0;return ok&&match;});var late=state.activities.filter(function(a){return new Date(a.plannedFinish+'T00:00:00')<new Date(todayISO()+'T00:00:00')&&Number(a.progress)<100;}).length;var tabs=[['all','All activities'],['open','Open'],['complete','Complete'],['late','Overdue']];var tabHtml=tabs.map(function(t){var n=t[0]==='all'?state.activities.length:t[0]==='open'?state.activities.filter(function(a){return statusForActivity(a)!=='Complete';}).length:t[0]==='complete'?state.activities.filter(function(a){return statusForActivity(a)==='Complete';}).length:late;return'<button class="subnav-tab '+(scheduleFilter===t[0]?'active':'')+'" data-schedule-filter="'+t[0]+'">'+t[1]+'<span>'+n+'</span></button>';}).join('');var body=rows.map(function(a){var status=statusForActivity(a);var delta=Math.round(Number(a.progress)-Number(a.plannedProgress||0));var deltaText=delta<0?delta+' pts':delta>0?'+'+delta+' pts':'On plan';var deltaClass=delta<0?'variance-positive':delta>0?'variance-negative':'variance-neutral';var matchingReports=state.reports.filter(function(r){return r.activityId===a.id&&r.status==='approved';}).length;return'<tr><td><span class="source-code">'+esc(a.id)+'</span><div class="activity-name"><small>WBS '+esc(a.wbs)+'</small></div></td><td><div class="activity-name"><strong>'+esc(a.name)+'</strong><small>'+esc(a.location)+' · '+esc(a.owner)+'</small></div></td><td><span class="discipline-tag">'+esc(a.discipline)+'</span></td><td>'+fmtDate(a.plannedStart,true)+'<br><small class="muted-text">to '+fmtDate(a.plannedFinish,true)+' · '+(durationDays(a.plannedStart,a.plannedFinish)||'—')+' calendar days</small></td><td>'+fmtDate(a.actualStart,true)+(a.actualStartTime?' · '+esc(a.actualStartTime):'')+'<br><small class="muted-text">to '+fmtDate(a.actualFinish,true)+(a.actualFinishTime?' · '+esc(a.actualFinishTime):'')+' · actual '+(durationDays(a.actualStart,a.actualFinish)||'—')+' days'+(durationDays(a.plannedStart,a.plannedFinish)&&durationDays(a.actualStart,a.actualFinish)?' · '+((durationDays(a.actualStart,a.actualFinish)-durationDays(a.plannedStart,a.plannedFinish)>0?'+':'' )+(durationDays(a.actualStart,a.actualFinish)-durationDays(a.plannedStart,a.plannedFinish))+'d vs plan'):'')+'</small></td><td class="progress-cell"><span class="progress-line"><span style="width:'+Math.min(100,Number(a.progress))+'%"></span></span><span class="progress-number">'+Number(a.progress)+'%</span></td><td class="'+deltaClass+'">'+deltaText+'</td><td>'+statusPill(status)+'</td><td><button class="table-link" data-activity="'+esc(a.id)+'">'+matchingReports+' update'+(matchingReports===1?'':'s')+'</button></td></tr>';}).join('');return'<section class="panel"><div class="panel-header"><div class="panel-heading"><h2>Baseline schedule and actuals</h2><p>Every change is linked back to its field source and reviewer.</p></div><div class="section-toolbar"><div class="search-wrap"><input class="search-field" id="scheduleSearch" placeholder="Search activity, ID, location" value="'+esc(scheduleSearch)+'"></div>'+(canRole()?'<button class="small-button" data-action="import-schedule">↑ Import schedule CSV</button>':'')+'</div></div><div class="subnav-tabs">'+tabHtml+'</div><div class="activity-table-wrap"><table class="activity-table"><thead><tr><th>Activity ID</th><th>Activity</th><th>Discipline</th><th>Planned dates</th><th>Actual dates</th><th>Progress</th><th>Variance</th><th>Status</th><th>Updates</th></tr></thead><tbody>'+(body||'<tr><td colspan="9"><div class="empty-state"><strong>No activities match</strong>Change the search or filter to see schedule items.</div></td></tr>')+'</tbody></table></div><div class="table-foot"><span>Showing '+rows.length+' of '+state.activities.length+' activities</span><span>Schedule source: demo CSV · last refreshed locally</span></div></section><div class="notice-box" style="margin-top:12px">Prototype note: activity variance compares captured progress with an illustrative planned-progress value. Replace sample dates and plan percentages with your approved schedule before presenting.</div>';}

  function renderInbox(){var active=state.reports.filter(function(r){return !r.archived;});var archived=state.reports.filter(function(r){return r.archived;});var all=(inboxFilter==='archived'&&canArchive()?archived:active).slice().sort(function(a,b){return(b.date||'').localeCompare(a.date||'');});var filtered=all.filter(function(r){return inboxFilter==='all'||(inboxFilter==='pending'&&(r.status==='pending'||r.status==='unmatched'))||(inboxFilter==='approved'&&r.status==='approved')||(inboxFilter==='unmatched'&&r.status==='unmatched')||(inboxFilter==='archived'&&r.archived);});var tabData=[['all','All reports',active.length],['pending','Needs review',pendingReports().length],['unmatched','Unmatched',active.filter(function(r){return r.status==='unmatched';}).length],['approved','Reviewed',active.filter(function(r){return r.status==='approved';}).length]];if(canArchive())tabData.push(['archived','Removed',archived.length]);var tabs=tabData.map(function(t){return'<button class="subnav-tab '+(inboxFilter===t[0]?'active':'')+'" data-inbox-filter="'+t[0]+'">'+t[1]+'<span>'+t[2]+'</span></button>';}).join('');var reports=filtered.map(function(r){var list=candidates(r);var best=(r.activityId?currentActivity(r.activityId):null)||((list[0]&&list[0].score>=.31)?list[0].activity:null);var score=best?matchScore(r,best):0;var icon=r.sourceType==='spreadsheet'?'▦':r.sourceType==='voice'?'◖':'≡';var iconClass=r.sourceType==='spreadsheet'?'spreadsheet':r.sourceType==='voice'?'voice':'';return'<article class="inbox-row"><div class="inbox-source-icon '+iconClass+'">'+icon+'</div><div class="inbox-main"><strong>'+esc(r.source)+' '+(r.isDefault?'<span class="role-badge">DEFAULT SAMPLE</span>':'')+' <span class="muted-text" style="font-weight:400">· '+esc(r.id)+'</span></strong><p>'+esc(r.text)+'</p><div class="inbox-meta">'+esc(r.reporter||'Imported report')+' · Added by '+esc(r.createdBy||'—')+' · '+esc(fmtDate(r.date,true))+'</div></div><div class="inbox-match">'+(best?'<strong>'+esc(best.id)+' · '+esc(best.name)+'</strong><small>'+esc(best.discipline)+' · '+scoreLabel(score)+' heuristic match</small><span class="review-score"><span class="'+scoreClass(score)+'" style="width:'+Math.round(score*100)+'%"></span></span>':'<strong>No confident link</strong><small>Choose an activity or keep it unmatched</small>')+'</div><div class="inbox-actions">'+statusPill(r.archived?'Removed':r.status)+(canReview()&&!r.archived?'<button class="icon-text-button '+(r.status==='pending'||r.status==='unmatched'?'primary-mini':'')+'" data-review="'+esc(r.id)+'">'+(r.status==='approved'?'View record':'Review')+'</button>':'')+(canArchive()?'<button class="icon-text-button" data-archive="'+esc(r.id)+'">'+(r.archived?'Restore':'Remove')+'</button>':'')+'</div></article>';}).join('');return'<section class="panel"><div class="panel-header"><div class="panel-heading"><h2>Incoming progress reports</h2><p>Review suggestions; no schedule value changes until you confirm.</p></div>'+(canArchive()&&active.some(function(r){return r.isDefault;})?'<button class="small-button" data-action="archive-defaults">Remove sample reports</button>':'')+(canImport()?'<button class="small-button" data-action="import-reports">＋ Import reports</button>':'')+'</div><div class="inbox-intro"><div class="inbox-intro-copy"><div class="inbox-big-icon">⇥</div><div><strong>One queue for reports from every discipline</strong><small>Text reports and spreadsheet CSVs are parsed locally, then linked to the activity register.</small></div></div><span class="mini-stat"><strong>'+pendingReports().length+'</strong> awaiting planner review</span></div><div class="subnav-tabs">'+tabs+'</div>'+(reports||'<div class="empty-state"><strong>No reports in this view</strong>Import a report or switch to another filter.</div>')+''+(canImport()?'<div class="dropzone" id="dropzone"><div class="drop-copy"><span class="drop-icon">↑</span><span><strong>Drop a TXT or CSV report here</strong><small>Use the included sample reports to see the matching flow. Save Excel sheets as CSV first.</small></span></div><button class="small-button" data-action="import-reports">Browse files</button></div>':'')+'</section><div class="notice-box" style="margin-top:12px">The match score is a transparent text-similarity heuristic, not a calibrated probability. Planner or admin approval is required before a schedule change.</div>';}

  function renderInsights(){var counts={};state.activities.forEach(function(a){counts[a.discipline]=counts[a.discipline]||{total:0,progress:0,late:0};counts[a.discipline].total++;counts[a.discipline].progress+=Number(a.progress)||0;if(new Date(a.plannedFinish+'T00:00:00')<new Date(todayISO()+'T00:00:00')&&Number(a.progress)<100)counts[a.discipline].late++;});var max=100;var bars=Object.keys(counts).map(function(k){var p=Math.round(counts[k].progress/counts[k].total);return'<div class="discipline-row"><label>'+esc(k)+'</label><div class="bar-track"><span style="width:'+p+'%"></span></div><strong>'+p+'%</strong></div>';}).join('');var causes=[],causeCounts={};state.reports.filter(function(r){return !r.archived&&r.status==='approved';}).forEach(function(r){var blocker=(r.extraction||{}).blocker||'';if(blocker)causeCounts[blocker]=(causeCounts[blocker]||0)+1;});Object.keys(causeCounts).forEach(function(k){causes.push([k,causeCounts[k]]);});return'<div class="progress-summary"><div class="summary-chip"><small>Average recorded progress</small><strong>'+Math.round(state.activities.reduce(function(s,a){return s+(Number(a.progress)||0);},0)/Math.max(1,state.activities.length))+'%</strong><span>Across current register</span></div><div class="summary-chip"><small>Approved reports</small><strong>'+state.reports.filter(function(r){return r.status==='approved';}).length+'</strong><span>Source linked and reviewed</span></div><div class="summary-chip"><small>Records needing review</small><strong>'+pendingReports().length+'</strong><span>Keep source detail visible</span></div></div><div class="insight-grid"><section class="insight-card"><h3>Progress by discipline</h3><p>Average completion in the current illustrative activity register.</p><div class="discipline-bars">'+bars+'</div></section><section class="insight-card"><h3>Reported delay signals</h3><p>Blockers named in approved source reports; counts are historical.</p><div class="cause-list">'+causes.map(function(c,i){return'<div class="cause-row"><i class="cause-bullet" style="opacity:'+(1-i*.12)+'"></i>'+c[0]+'<span class="cause-value">'+c[1]+' mentions</span></div>';}).join('')+'</div></section></div><div class="memory-callout"><span>◉</span><div><strong>Build institutional memory from reviewed actuals</strong><p>Once enough verified projects exist, consistent records can support duration benchmarks and recurring bottleneck analysis. This demo uses only a small synthetic dataset, so it does not claim statistical predictions.</p></div></div>';
  }
  function renderAgent(){return'<section class="agent-grid"><div class="panel agent-entry"><div class="panel-header"><div class="panel-heading"><h2>Tell the Time Agent what happened</h2><p>Local extraction and schedule matching; no cloud AI provider is configured.</p></div><span class="role-badge">'+esc(authUser.role)+'</span></div><div class="agent-form"><label class="field-label" for="agentText">Supervisor update</label><textarea class="textarea agent-textarea" id="agentText" placeholder="Example: Line 24 spool erection started at 8:30 this morning in Unit B. Four spools are installed; progress is about 65%."></textarea><div class="agent-controls"><select class="select" id="agentDiscipline"><option value="">Auto-detect discipline</option><option>Civil</option><option>Piping</option><option>Electrical</option><option>Instrumentation</option><option>Equipment</option><option>HSE</option></select><input class="input" type="date" id="agentDate" value="'+todayISO()+'"><button class="small-button" id="agentVoiceButton" type="button">◉ Dictate update</button><button class="button button-primary" data-agent-action="analyze" type="button">Analyze update</button></div><div class="source-note">Voice dictation uses the browser’s optional speech recognition. Audio is not saved by SiteLink. Check the transcript before analysis. Scores are heuristic rankings, not calibrated probabilities.</div></div><div id="agentResult" class="agent-result"><div class="empty-state"><strong>Ready for a field update</strong>Enter text or use dictation, then select Analyze update. Saving adds a pending report; it does not change the schedule.</div></div></div><aside class="insight-card agent-guide"><h3>Safe capture flow</h3><div class="agent-steps"><div><b>1</b><span>State activity, location, and event clearly.</span></div><div><b>2</b><span>Review extracted dates, times, progress, and evidence.</span></div><div><b>3</b><span>Choose a candidate only when it is the right schedule node.</span></div><div><b>4</b><span>Save to the inbox. A Planner approves or corrects the match.</span></div></div><div class="notice-box">No activity ID or date is fabricated. Missing details stay blank and uncertain links stay unmatched.</div></aside></section>';}
  function renderConflicts(){var conflicts=(state.intelligence&&state.intelligence.conflicts)||[];var unresolved=conflicts.filter(function(c){return c.unresolved;});var cards=conflicts.map(function(c){var values=c.values.map(function(v){return'<div class="conflict-source"><div><strong>'+esc(String(v.value)+(c.field==='progress'?'%':''))+'</strong><small>'+esc(v.source)+' · '+esc(v.reporter)+' · '+esc(v.source_type)+' · '+esc(v.report_id)+'</small></div><button class="table-link" data-review="'+esc(v.report_id)+'">Review source ↗</button></div>';}).join('');return'<article class="conflict-card '+(c.unresolved?'is-open':'is-resolved')+'"><div class="conflict-heading"><div><span class="eyebrow">'+esc(c.field_label)+' · '+esc(fmtDate(c.report_date,true))+'</span><h3>'+esc(c.activity_id)+' · '+esc(c.activity_name)+'</h3><small>'+esc(c.discipline)+' · '+esc(c.state)+'</small></div>'+statusPill(c.unresolved?'Needs review':'approved')+'</div><div class="conflict-values">'+values+'</div><div class="source-note">Different source values are shown as submitted. SiteLink does not choose a winner automatically; the Planner records a final decision in report review.</div></article>';}).join('');return'<div class="progress-summary"><div class="summary-chip"><small>Conflicts detected</small><strong>'+conflicts.length+'</strong><span>Same activity and report date</span></div><div class="summary-chip"><small>Needs planner decision</small><strong>'+unresolved.length+'</strong><span>At least one source remains pending</span></div><div class="summary-chip"><small>Progress conflict rule</small><strong>≥10 pts</strong><span>Dates/status also compared</span></div></div><section class="panel"><div class="panel-header"><div class="panel-heading"><h2>Source reconciliation queue</h2><p>Materially different report values are displayed side by side for Planner review.</p></div></div><div class="conflict-list">'+(cards||'<div class="empty-state"><strong>No conflicts detected</strong>Import reports for the same activity and date to compare values.</div>')+'</div></section><div class="notice-box" style="margin-top:12px">A conflict is considered reviewed after each contributing report is approved. Review the sources before deciding which value to keep.</div>';}
  function renderMissing(){var rows=(state.intelligence&&state.intelligence.missing_updates)||[];var body=rows.map(function(item){return'<tr><td><span class="source-code">'+esc(item.activity_id)+'</span></td><td><div class="activity-name"><strong>'+esc(item.activity_name)+'</strong><small>'+esc(item.discipline)+' · '+esc(item.owner)+'</small></div></td><td>'+esc(item.last_update==='No report received'?item.last_update:fmtDate(item.last_update,true))+'</td><td><span class="match-pill '+(item.missing_hours>=72?'pill-red':'pill-amber')+'">'+Math.floor(item.missing_hours/24)+'d '+(item.missing_hours%24)+'h</span></td><td>'+item.cadence_hours+' hours</td><td>'+statusPill(item.status)+'</td><td>'+(canImport()?'<button class="table-link" data-missing-log="'+esc(item.activity_id)+'">Log / review update</button>':'Read only')+'</td></tr>';}).join('');return'<div class="memory-callout"><span>◷</span><div><strong>Completeness check, not a delay verdict</strong><p>Open activities are flagged after their reporting cadence elapses. Default cadence is 48 hours; set update_cadence_hours in a schedule CSV to customize it.</p></div></div><section class="panel" style="margin-top:14px"><div class="panel-header"><div class="panel-heading"><h2>Open activities without a recent linked report</h2><p>Age is measured from the last linked report date, or planned start when no report is linked.</p></div><span class="match-pill '+(rows.length?'pill-amber':'pill-green')+'">'+rows.length+' items</span></div><div class="activity-table-wrap"><table class="activity-table"><thead><tr><th>Activity ID</th><th>Owner / discipline</th><th>Last update</th><th>Missing for</th><th>Expected cadence</th><th>Schedule state</th><th>Action</th></tr></thead><tbody>'+(body||'<tr><td colspan="7"><div class="empty-state"><strong>No stale updates</strong>Every active activity is inside its expected reporting window.</div></td></tr>')+'</tbody></table></div><div class="table-foot"><span>Sorted by oldest update first.</span><span>Unmatched reports do not count as activity updates.</span></div></section>';}
  function renderMemory(){var data=state.intelligence||{},fps=data.fingerprints||[],chains=data.why_chains||[];var cards=fps.map(function(f){var variance=Number(f.variance_days)||0;var ev=(f.evidence||[]).map(function(e){return esc(e.source)+' ('+esc(e.report_id)+')';}).join(' · ')||'No linked report';return'<article class="fingerprint-card"><div class="fingerprint-top"><div><span class="source-code">'+esc(f.activity_id)+'</span><h3>'+esc(f.activity_name)+'</h3><small>'+esc(f.discipline)+' · '+esc(f.contractor)+'</small></div><span class="match-pill '+(variance>0?'pill-amber':variance<0?'pill-green':'pill-gray')+'">'+(variance>0?'+':'')+variance+' day'+(Math.abs(variance)===1?'':'s')+'</span></div><div class="fingerprint-metrics"><div><small>Planned</small><strong>'+f.planned_days+' days</strong><span>'+esc(fmtDate(f.planned_start,true))+' → '+esc(fmtDate(f.planned_finish,true))+'</span></div><div><small>Actual</small><strong>'+f.actual_days+' days</strong><span>'+esc(fmtDate(f.actual_start,true))+' → '+esc(fmtDate(f.actual_finish,true))+'</span></div></div><div class="fingerprint-detail"><b>Reported delay cause:</b> '+esc(f.delay_cause)+' <small>('+esc(f.cause_source)+')</small></div><div class="fingerprint-detail"><b>Evidence:</b> '+ev+'</div></article>';}).join('');var why=chains.map(function(c){return'<article class="why-card"><div class="why-node cause"><small>'+esc(c.cause_status.toUpperCase())+'</small><strong>'+esc(c.cause)+'</strong><span>'+esc(c.source)+' · '+esc(c.report_id)+'</span></div><div class="why-arrow">↓</div><div class="why-node"><small>AFFECTED ACTIVITY</small><strong>'+esc(c.activity_id)+' · '+esc(c.activity_name)+'</strong></div>'+(c.downstream||[]).map(function(d){return'<div class="why-arrow">↓</div><div class="why-node downstream"><small>POSSIBLE SCHEDULE-LINKED EXPOSURE</small><strong>'+esc(d.activity_id)+' · '+esc(d.activity_name)+'</strong></div>';}).join('')+'<p>'+esc(c.downstream_label)+'</p></article>';}).join('');var sums=data.memory_summary||{};var avg=(sums.answer||'').match(/average duration is ([\d.]+)/i);return'<div class="progress-summary"><div class="summary-chip"><small>Completed fingerprints</small><strong>'+fps.length+'</strong><span>Need planned and actual dates</span></div><div class="summary-chip"><small>Average actual duration</small><strong>'+(avg?esc(avg[1])+' days':'—')+'</strong><span>Small sample observation only</span></div><div class="summary-chip"><small>Reported why-chains</small><strong>'+chains.length+'</strong><span>Based on explicit blocker language</span></div></div><section class="panel memory-query"><div class="panel-header"><div class="panel-heading"><h2>Ask project execution memory</h2><p>Queries are answered from stored sample fingerprints; no predictive claim is made.</p></div></div><div class="memory-question"><input class="input" id="memoryQuestion" value="What was the average actual duration?" placeholder="Average duration, reported delay causes, or discipline bottlenecks"><button class="button button-primary" data-agent-action="memory">Ask memory</button></div><div id="memoryAnswer" class="memory-answer">'+esc(sums.answer||'Ask a question to query the saved execution records.')+'<small>'+esc(sums.basis||'Current sample data')+'</small></div></section><div class="divider-label">COMPLETED EXECUTION FINGERPRINTS</div><section class="fingerprint-grid">'+(cards||'<div class="empty-state"><strong>No complete fingerprints yet</strong>Approve a report with actual start and finish dates on a completed activity.</div>')+'</section><div class="divider-label">REPORTED CAUSE → SCHEDULE-LINKED EXPOSURE</div><section class="why-grid">'+(why||'<div class="empty-state"><strong>No evidence-backed why-chain available</strong>Report an explicit blocker and add predecessor links in the schedule.</div>')+'</section><div class="notice-box" style="margin-top:12px">Durations use inclusive calendar days. A reported blocker is not asserted as a verified root cause. Downstream nodes are possible exposures from imported predecessor links, not proof of causality.</div>';}
  function renderAudit(){var rows=state.audit.slice().map(function(a){var initials=(a.actor||'System').split(' ').map(function(x){return x.charAt(0);}).join('').slice(0,2).toUpperCase();var snapshots=(a.before||a.after)?'<details class="audit-detail"><summary>View record details</summary>'+(a.before?'<strong>Before</strong><pre>'+esc(JSON.stringify(a.before,null,2))+'</pre>':'')+(a.after?'<strong>After</strong><pre>'+esc(JSON.stringify(a.after,null,2))+'</pre>':'')+'</details>':'';return'<tr><td>'+esc(fmtDateTime(a.time))+'</td><td><span class="audit-actor"><i class="actor-avatar">'+esc(initials)+'</i><span>'+esc(a.actor)+'<br><small class="muted-text">'+esc(a.role||'')+'</small></span></span></td><td><div class="audit-what">'+esc(a.what||a.action)+'</div><small class="muted-text">'+esc(a.action)+'</small>'+snapshots+'</td><td><div class="audit-location">'+esc(a.where||'SiteLink workspace')+'</div>'+(a.sourceIp?'<small class="muted-text">Device IP '+esc(a.sourceIp)+'</small>':'')+'<span class="source-code">'+esc(a.record)+'</span></td><td><div class="audit-why">'+esc(a.why||'—')+'</div></td></tr>';}).join('');return'<section class="panel"><div class="panel-header"><div class="panel-heading"><h2>Who changed what, when, where, and why</h2><p>Server-recorded history for report additions, reviews, removals, and access changes. Expand a record to see its before and after details.</p></div><button class="small-button" data-action="export-audit">↓ Export audit CSV</button></div><div class="activity-table-wrap"><table class="audit-table"><thead><tr><th>When (UTC)</th><th>Who / role</th><th>What changed</th><th>Where / source</th><th>Why</th></tr></thead><tbody>'+(rows||'<tr><td colspan="5"><div class="empty-state">No audit events yet.</div></td></tr>')+'</tbody></table></div><div class="table-foot"><span>'+state.audit.length+' events retained on the workspace server</span><span>Removed reports remain recorded in the audit history</span></div></section><div class="notice-box" style="margin-top:12px">Audit history is stored in SQLite on the server. Back up the data folder before moving or redeploying the workspace.</div>';}
  function renderUsers(){
    if(!authUser||authUser.role!=='Admin')return '<section class="panel"><div class="empty-state"><strong>Administrator access required</strong>You do not have permission to manage accounts.</div></section>';
    var projects=state.projects||[],users=state.users||[];
    var projectName=function(id){var p=projects.find(function(x){return x.id===id;});return p?p.name:id;};
    var rows=users.map(function(u){var assigned=u.role==='Admin'?'All workspace projects':((u.projects||[]).map(projectName).join(', ')||'No project assigned');return '<tr><td><div class="task-cell"><span class="actor-avatar">'+esc(initials(u.name))+'</span><span><strong>'+esc(u.name)+'</strong><small>'+esc(u.username)+'</small></span></div></td><td><select class="select" data-user-role="'+u.id+'" '+(u.id===authUser.id?'disabled':'')+'><option '+(u.role==='Admin'?'selected':'')+'>Admin</option><option '+(u.role==='Project Manager'?'selected':'')+'>Project Manager</option><option '+(u.role==='Planner'?'selected':'')+'>Planner</option><option '+(u.role==='Supervisor'?'selected':'')+'>Supervisor</option><option '+(u.role==='Contractor'?'selected':'')+'>Contractor</option><option '+(u.role==='Viewer'?'selected':'')+'>Viewer</option></select></td><td><div>'+esc(assigned)+'</div><small>'+(u.active?'<span class="account-state">Active</span>':'<span class="account-state disabled">Disabled</span>')+'</small></td><td>'+esc(fmtDate((u.createdAt||'').slice(0,10),true))+'</td><td>'+esc(u.lastLogin?fmtDateTime(u.lastLogin):'Never')+'</td><td><button class="table-link" data-user-edit="'+u.id+'" data-user-name="'+esc(u.name)+'" data-user-username="'+esc(u.username)+'">Edit</button> · <button class="table-link" data-user-reset="'+u.id+'" data-user-name="'+esc(u.name)+'">Reset password</button> · <button class="table-link" data-user-toggle="'+u.id+'" data-active="'+u.active+'">'+(u.active?'Disable':'Enable')+'</button>'+(u.id===authUser.id?'':' · <button class="table-link danger-link" data-user-delete="'+u.id+'" data-user-name="'+esc(u.name)+'">Delete</button>')+'</td></tr>';}).join('');
    var projectCards=projects.map(function(pr){return '<article class="project-admin-card"><div><h3>'+esc(pr.name)+'</h3><p>'+esc([pr.client,pr.phase].filter(Boolean).join(' · ')||'Project workspace')+'</p></div><div><button class="table-link" data-project-edit="'+esc(pr.id)+'">Edit</button> · <button class="table-link" data-project-members="'+esc(pr.id)+'">Manage members</button></div></article>';}).join('');
    return '<section class="panel"><div class="panel-header"><div class="panel-heading"><h2>Workspace accounts</h2><p>Each teammate has an independent session. Access is scoped to assigned projects and enforced by the server.</p></div><button class="button button-primary" id="addUserButton">＋ Add user</button></div><div class="activity-table-wrap"><table class="activity-table"><thead><tr><th>Account</th><th>Role</th><th>Project access / state</th><th>Created</th><th>Last login</th><th>Admin actions</th></tr></thead><tbody>'+(rows||'<tr><td colspan="6"><div class="empty-state">No accounts found.</div></td></tr>')+'</tbody></table></div><div class="table-foot"><span>'+users.length+' account'+(users.length===1?'':'s')+'</span><span>Role, access, password, and project changes are audited</span></div></section><section class="panel" style="margin-top:14px"><div class="panel-header"><div class="panel-heading"><h2>Projects and memberships</h2><p>Projects are isolated. Add a member to grant access, then adjust the member’s role permissions.</p></div><button class="button button-secondary" id="addProjectButton">＋ Create project</button></div><div class="project-admin-list">'+(projectCards||'<div class="empty-state">No active projects.</div>')+'</div><div class="table-foot"><span>'+projects.length+' project'+(projects.length===1?'':'s')+'</span><span>Admins can access all projects in this workspace</span></div></section><div class="insight-grid" style="margin-top:14px"><section class="insight-card"><h3>Admin</h3><p>Manage workspace users, projects, memberships, and audit history.</p></section><section class="insight-card"><h3>Planner</h3><p>Review and approve matches only in assigned projects and with granted permissions.</p></section><section class="insight-card"><h3>Supervisor</h3><p>Submit assigned-project reports. An Admin may grant additional review permissions.</p></section><section class="insight-card"><h3>Viewer</h3><p>Read-only access to assigned projects.</p></section></div><div class="notice-box" style="margin-top:12px">Use passwords that are 6–8 characters. Share credentials privately; this prototype does not send invitations.</div>';
  }
  function openArchiveModal(id){if(!canArchive()){toast('Administrator access is required to remove or restore reports.','error');return;}var r=state.reports.find(function(x){return x.id===id;});if(!r)return;var restoring=!!r.archived;var modal='<div class="modal-backdrop" id="modalBackdrop"><section class="modal-card" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><header class="modal-header"><div><h2 id="modalTitle">'+(restoring?'Restore report':'Remove report')+'</h2><p>'+esc(r.id)+' · '+esc(r.source)+'</p></div><button class="modal-close" data-close-modal aria-label="Close">×</button></header><div class="modal-body"><div class="source-note">'+esc(r.text)+'</div><div class="field" style="margin-top:14px"><label for="archiveReason">Why are you '+(restoring?'restoring':'removing')+' this report? (required)</label><textarea class="textarea" id="archiveReason" placeholder="Explain the reason. This is kept in the audit trail." required></textarea><span class="field-hint">At least 8 characters. Removed reports are archived, not erased.</span></div></div><footer class="modal-footer"><span class="field-hint">Only administrators can do this.</span><div style="display:flex;gap:8px"><button class="button button-secondary" data-close-modal>Cancel</button><button class="button button-primary" id="confirmArchive">'+(restoring?'Restore report':'Remove report')+'</button></div></footer></section></div>';document.getElementById('modalRoot').innerHTML=modal;document.querySelectorAll('[data-close-modal]').forEach(function(b){b.addEventListener('click',closeModal);});document.getElementById('modalBackdrop').addEventListener('click',function(e){if(e.target.id==='modalBackdrop')closeModal();});document.getElementById('confirmArchive').addEventListener('click',function(){var reason=document.getElementById('archiveReason').value.trim();if(reason.length<8){toast('Please add a clear reason (at least 8 characters).','error');return;}r.archived=!restoring;var oldFilter=inboxFilter;inboxFilter=restoring?'all':'archived';closeModal();save(reason).then(function(ok){if(ok){navigate('inbox');if(!restoring)inboxFilter='archived';render();toast(restoring?'Report restored.':'Report removed from the active inbox and preserved in the audit.');}else{inboxFilter=oldFilter;}});});}
  function openUserModal(){
    if(!authUser||authUser.role!=='Admin')return;
    var assignment=(state.projects||[]).map(function(p){return '<label class="project-check"><input type="checkbox" data-new-project="'+esc(p.id)+'" '+(p.id===activeProjectId?'checked':'')+'><span><strong>'+esc(p.name)+'</strong><small>'+esc([p.client,p.phase].filter(Boolean).join(' · '))+'</small></span></label>';}).join('');
    var modal='<div class="modal-backdrop" id="modalBackdrop"><section class="modal-card wide" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><header class="modal-header"><div><h2 id="modalTitle">Add workspace user</h2><p>Create a login and select the projects this teammate may access.</p></div><button class="modal-close" data-close-modal aria-label="Close">×</button></header><div class="modal-body"><div class="form-grid"><div class="field"><label for="newUserName">Display name</label><input class="input" id="newUserName" required></div><div class="field"><label for="newUsername">Username</label><input class="input" id="newUsername" required minlength="3"></div><div class="field"><label for="newUserPassword">Temporary password</label><input class="input" id="newUserPassword" type="password" required minlength="6" maxlength="8"><span class="field-hint">Password must be 6–8 characters. Share it securely.</span></div><div class="field"><label for="newUserRole">Role</label><select class="select" id="newUserRole"><option>Project Manager</option><option>Planner</option><option>Supervisor</option><option>Contractor</option><option>Viewer</option><option>Admin</option></select></div><div class="field full"><label>Project assignments</label><div class="project-check-list">'+(assignment||'<span class="field-hint">Create a project first.</span>')+'</div></div><div class="field full"><label for="newUserReason">Why is this account being added? (required)</label><textarea class="textarea" id="newUserReason" required placeholder="Team member and access purpose"></textarea></div></div></div><footer class="modal-footer"><span class="field-hint">Account creation is audited.</span><div style="display:flex;gap:8px"><button class="button button-secondary" data-close-modal>Cancel</button><button class="button button-primary" id="createUserButton">Create account</button></div></footer></section></div>';
    document.getElementById('modalRoot').innerHTML=modal;document.querySelectorAll('[data-close-modal]').forEach(function(b){b.addEventListener('click',closeModal);});document.getElementById('modalBackdrop').addEventListener('click',function(e){if(e.target.id==='modalBackdrop')closeModal();});document.getElementById('createUserButton').addEventListener('click',createUser);
  }
  function createUser(){var data={name:document.getElementById('newUserName').value.trim(),username:document.getElementById('newUsername').value.trim(),password:document.getElementById('newUserPassword').value,role:document.getElementById('newUserRole').value,reason:document.getElementById('newUserReason').value.trim(),projectIds:Array.from(document.querySelectorAll('[data-new-project]:checked')).map(function(x){return x.getAttribute('data-new-project');})};if(!data.name||data.username.length<3||data.password.length<6||data.password.length>8||data.reason.length<8){toast('Complete each field; password must be 6–8 characters and reason 8.','error');return;}apiRequest('/api/users','POST',data).then(function(result){state.users=result.users;closeModal();render();toast('Workspace account created with project access.');apiRequest('/api/state','GET').then(function(s){state=s;syncedSnapshot=clone(s);render();});}).catch(function(error){toast(error.message,'error');});}
  function changeUserRole(select){if(!authUser||authUser.role!=='Admin')return;var why=window.prompt('Why are you changing this role? This reason is audited.');if(why===null||why.trim().length<8){toast('A reason of at least 8 characters is required.','error');render();return;}apiRequest('/api/users/'+select.getAttribute('data-user-role'),'PATCH',{role:select.value,reason:why.trim()}).then(function(result){state.users=result.users;return apiRequest('/api/state','GET');}).then(function(s){state=s;syncedSnapshot=clone(s);render();toast('User role updated.');}).catch(function(error){toast(error.message,'error');render();});}
