  function approveReport(id){
    if(!canApprove()){toast('Approval permission is required.','error');return;}
    var r=state.reports.find(function(x){return x.id===id;});if(!r||r.archived)return;
    var reason=document.getElementById('reviewReason').value.trim();if(reason.length<8){toast('Add a reason of at least 8 characters.','error');return;}
    var picked=document.querySelector('input[name="candidate"]:checked');if(!picked){toast('Select an activity or keep this report unmatched.','error');return;}
    var a=currentActivity(picked.value);if(!a){toast('That activity is no longer in the register.','error');return;}
    var start=document.getElementById('reviewStart').value,end=document.getElementById('reviewEnd').value;
    var startTime=document.getElementById('reviewStartTime').value,endTime=document.getElementById('reviewEndTime').value;
    var progress=document.getElementById('reviewProgress').value,reviewer=document.getElementById('reviewReviewer').value.trim()||authUser.name;
    var note=document.getElementById('reviewNote').value.trim();
    if(start&&end&&end<start){toast('Finish date cannot be earlier than start date.','error');return;}
    if(startTime&&!start||endTime&&!end){toast('Add the corresponding actual date when you enter an actual time.','error');return;}
    if(progress!==''&&(Number(progress)<0||Number(progress)>100||!Number.isFinite(Number(progress)))){toast('Progress must be from 0 to 100 percent.','error');return;}
    r.activityId=a.id;r.suggestedActivityId=a.id;r.actualStart=start;r.actualEnd=end;r.actualStartTime=startTime;r.actualEndTime=endTime;
    r.progress=progress===''?'':Number(progress);r.status='approved';r.reviewer=reviewer;r.note=note;r.reviewedAt=new Date().toISOString();
    if(start&&!a.actualStart)a.actualStart=start;if(end)a.actualFinish=end;
    if(startTime)a.actualStartTime=startTime;if(endTime)a.actualFinishTime=endTime;
    if(r.progress!==''&&r.progress>=0)a.progress=r.progress;else if(end)a.progress=100;
    if(Number(a.progress)>=100){a.progress=100;a.status='Complete';if(end)a.actualFinish=end;}
    else if(start||Number(a.progress)>0)a.status='In progress';
    addAudit(reviewer,'Approved progress update',r.id,a.id+' · '+(end?'actual finish '+end:start?'actual start '+start:'progress '+(r.progress===''?'not changed':r.progress+'%')));
    closeModal();render();save(reason).then(function(ok){if(ok)toast('Update linked to '+a.id+' and recorded in the audit trail.');});
  }
  function keepUnmatched(id){if(!canApprove()){toast('Approval permission is required.','error');return;}var r=state.reports.find(function(x){return x.id===id;});var reason=document.getElementById('reviewReason').value.trim();if(!r)return;if(reason.length<8){toast('Add a reason of at least 8 characters.','error');return;}r.activityId='';r.suggestedActivityId='';r.confidence=0;r.status='unmatched';var note=document.getElementById('reviewNote');if(note&&note.value.trim())r.note=note.value.trim();addAudit(authUser.name,'Kept report unmatched',r.id,'Planner review required · source retained');closeModal();render();save(reason).then(function(ok){if(ok)toast('Report retained for planner follow-up.');});}
  function closeModal(){document.getElementById('modalRoot').innerHTML='';}

  function openLogModal(){if(!canImport()){toast('Your role cannot add reports.','error');return;}var modal='<div class="modal-backdrop" id="modalBackdrop"><section class="modal-card" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><header class="modal-header"><div><h2 id="modalTitle">Log a site update</h2><p>Capture a supervisor update; a planner still reviews the schedule match.</p></div><button class="modal-close" data-close-modal aria-label="Close">×</button></header><div class="modal-body"><div class="form-grid"><div class="field full"><label for="logText">What happened on site?</label><textarea class="textarea" id="logText" placeholder="Example: Piping crew started erecting Line 24-XX in Unit B today. 4 spools installed; about 65% complete."></textarea><span class="field-hint">Use natural language. Mention the activity, location, date, and progress when known.</span></div><div class="field"><label for="logDiscipline">Discipline</label><select class="select" id="logDiscipline"><option value="">Auto-detect from update</option><option>Civil</option><option>Piping</option><option>Electrical</option><option>Instrumentation</option><option>Equipment</option><option>HSE</option></select></div><div class="field"><label for="logDate">Report date</label><input class="input" type="date" id="logDate" value="'+todayISO()+'"></div><div class="field"><label for="logReporter">Supervisor / reporter</label><input class="input" id="logReporter" value="Site supervisor"></div><div class="field"><label for="logProgress">Progress (if stated)</label><input class="input" id="logProgress" type="number" min="0" max="100" placeholder="e.g. 65"></div><div class="field full"><label for="logReason">Why are you adding this report? (required)</label><textarea class="textarea" id="logReason" placeholder="Purpose or context for this site update"></textarea><span class="field-hint">At least 8 characters; this will be visible in the audit trail.</span></div><div class="field full"><div class="notice-box">This prototype extracts common date, status, discipline, and percent patterns locally. It does not call an LLM or speech service.</div></div></div></div><footer class="modal-footer"><button class="small-button" id="loadExampleLog">Use example</button><div style="display:flex;gap:8px"><button class="button button-secondary" data-close-modal>Cancel</button><button class="button button-primary" id="saveLogButton">Add to report inbox</button></div></footer></section></div>';document.getElementById('modalRoot').innerHTML=modal;document.querySelectorAll('[data-close-modal]').forEach(function(b){b.addEventListener('click',closeModal);});document.getElementById('modalBackdrop').addEventListener('click',function(e){if(e.target.id==='modalBackdrop')closeModal();});document.getElementById('loadExampleLog').addEventListener('click',function(){document.getElementById('logText').value='Piping team started erecting Line 24-XX in Unit B today. Four spools are installed and progress is 65%.';document.getElementById('logDiscipline').value='Piping';document.getElementById('logProgress').value='65';});document.getElementById('saveLogButton').addEventListener('click',saveLog);}
  function saveLog(){if(!canImport())return;var reason=document.getElementById('logReason').value.trim();if(reason.length<8){toast('Add a reason of at least 8 characters.','error');return;}var text=document.getElementById('logText').value.trim();if(!text){toast('Add a short site update first.','error');return;}var discipline=document.getElementById('logDiscipline').value||detectDiscipline(text);var date=document.getElementById('logDate').value||todayISO();var prog=document.getElementById('logProgress').value;var extracted=extractSignals(text,date);var id=nextReportId();var r={id:id,date:date,discipline:discipline,text:text,reporter:document.getElementById('logReporter').value.trim()||'Site supervisor',source:'Supervisor update · typed',sourceType:'manual',actualStart:extracted.start||'',actualEnd:extracted.end||'',progress:prog===''?extracted.progress:Math.max(0,Math.min(100,Number(prog))),status:'pending',activityId:'',createdAt:new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'}),note:'New supervisor update. Review the suggested schedule match.'};state.reports.unshift(r);addAudit(authUser.name,'Logged site update',r.id,discipline+' · '+date);closeModal();currentView='inbox';render();save(reason).then(function(ok){if(ok)toast('Update added and attributed to '+authUser.name+'.');});}
  function nextReportId(){var max=0;state.reports.forEach(function(r){var m=(r.id||'').match(/(\d+)$/);if(m)max=Math.max(max,Number(m[1]));});return'RPT-'+todayISO().slice(2,4)+todayISO().slice(5,7)+todayISO().slice(8,10)+'-'+String(max+1).padStart(3,'0');}
  function detectDiscipline(text){var s=text.toLowerCase();var d=[['Piping',['pipe','spool','hydrotest','line 24']],['Electrical',['cable','electrical','substation','earthing']],['Instrumentation',['instrument','transmitter','calibrat','loop check','pt-']],['Civil',['concrete','foundation','backfill','trench','civil']],['Equipment',['pump','coupling','alignment','mechanical']],['HSE',['permit','safety','confined-space','hse']]];for(var i=0;i<d.length;i++)if(d[i][1].some(function(k){return s.indexOf(k)>=0;}))return d[i][0];return'';}
  function extractSignals(text,defaultDate){var s=text.toLowerCase();var start='',end='',progress='';var iso=s.match(/\b(20\d{2})-(\d{1,2})-(\d{1,2})\b/);var d=defaultDate||todayISO();if(iso)d=iso[1]+'-'+String(iso[2]).padStart(2,'0')+'-'+String(iso[3]).padStart(2,'0');var p=s.match(/\b(100|[1-9]?\d)\s*%/);if(p)progress=Number(p[1]);if(/\b(started|begin|began|commenced|mobilized|mobilised)\b/.test(s))start=d;if(/\b(completed|complete|finished|closed out|done)\b/.test(s)){end=d;progress=100;}return{start:start,end:end,progress:progress};}

  function openImportModal(){if(!canImport()){toast('Your role cannot import reports.','error');return;}var modal='<div class="modal-backdrop" id="modalBackdrop"><section class="modal-card" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><header class="modal-header"><div><h2 id="modalTitle">Import site reports</h2><p>Choose a report file or paste one supervisor update.</p></div><button class="modal-close" data-close-modal aria-label="Close">×</button></header><div class="modal-body"><div class="field" style="margin-bottom:13px"><label for="importReason">Why are these report(s) being added? (required)</label><input class="input" id="importReason" placeholder="For example: daily site reports for 29 Sep"><span class="field-hint">At least 8 characters. Applies to reports in this import.</span></div><div class="file-choice"><button class="file-tile" id="chooseTextFile"><div class="tile-icon">≡</div><strong>Free-text report</strong><small>Import a .txt site diary or daily progress note. One file becomes one review record.</small></button><button class="file-tile" id="chooseCsvFile"><div class="tile-icon">▦</div><strong>Discipline spreadsheet</strong><small>Import a .csv exported from Excel. Include date, discipline, text, and optional activity ID.</small></button></div><div class="divider-label">OR ADD A REPORT DIRECTLY</div><div class="form-grid"><div class="field full"><label for="pasteReportText">Report text</label><textarea class="textarea" id="pasteReportText" placeholder="Paste a daily report or site-diary entry here..."></textarea></div><div class="field"><label for="pasteDiscipline">Discipline (optional)</label><select class="select" id="pasteDiscipline"><option value="">Auto-detect</option><option>Civil</option><option>Piping</option><option>Electrical</option><option>Instrumentation</option><option>Equipment</option><option>HSE</option></select></div><div class="field"><label for="pasteReportDate">Report date</label><input class="input" type="date" id="pasteReportDate" value="'+todayISO()+'"></div></div><div class="divider-label">CSV COLUMNS</div><div class="source-note">Recommended headers: report_id, report_date, discipline, text, reporter, actual_start, actual_end, progress, activity_id. Extra columns are ignored.</div></div><footer class="modal-footer"><button class="sample-download" id="downloadSampleReports">Download sample CSV</button><div style="display:flex;gap:8px"><button class="button button-secondary" data-close-modal>Cancel</button><button class="button button-primary" id="pasteImportButton">Add pasted report</button></div></footer></section></div>';document.getElementById('modalRoot').innerHTML=modal;document.querySelectorAll('[data-close-modal]').forEach(function(b){b.addEventListener('click',closeModal);});document.getElementById('modalBackdrop').addEventListener('click',function(e){if(e.target.id==='modalBackdrop')closeModal();});document.getElementById('chooseTextFile').addEventListener('click',beginReportFileImport);document.getElementById('chooseCsvFile').addEventListener('click',beginReportFileImport);document.getElementById('pasteImportButton').addEventListener('click',importPastedReport);document.getElementById('downloadSampleReports').addEventListener('click',function(){downloadText('sample_progress_updates.csv',sampleReportCsv(),'text/csv');});}
  function importPastedReport(){if(!canImport())return;var reason=document.getElementById('importReason').value.trim();var text=document.getElementById('pasteReportText').value.trim();if(reason.length<8){toast('Add a reason of at least 8 characters.','error');return;}if(!text){toast('Paste a report before importing.','error');return;}var discipline=document.getElementById('pasteDiscipline').value||detectDiscipline(text);var date=document.getElementById('pasteReportDate').value||todayISO();addReportFromText(text,discipline,date,'Pasted site report','text/plain');closeModal();navigate('inbox');save(reason).then(function(ok){if(ok)toast('Site report added and attributed to '+authUser.name+'.');});}
  function addReportFromText(text,discipline,date,source,sourceType,metadata){var signals=extractSignals(text,date);var r={id:(metadata&&metadata.id)||nextReportId(),externalId:(metadata&&metadata.externalId)||'',date:(metadata&&metadata.date)||date||todayISO(),discipline:(metadata&&metadata.discipline)||discipline||detectDiscipline(text),text:text,reporter:(metadata&&metadata.reporter)||'Imported report',source:source||'Site report · text',sourceType:sourceType||'text',actualStart:(metadata&&metadata.actualStart)||signals.start,actualEnd:(metadata&&metadata.actualEnd)||signals.end,progress:(metadata&&metadata.progress!==undefined&&metadata.progress!==''?Number(metadata.progress):signals.progress),status:'pending',activityId:(metadata&&metadata.activityId)||'',createdAt:new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'}),note:'Imported locally. Verify extracted dates and schedule link before confirming.'};state.reports.unshift(r);addAudit(authUser?authUser.name:'System','Imported site report',r.id,r.source);}
  function beginReportFileImport(){var input=document.getElementById('importReason');var reason=input?input.value.trim():pendingImportReason;if(reason.length<8){toast('Add a reason of at least 8 characters before importing.','error');return;}pendingImportReason=reason;closeModal();document.getElementById('reportFileInput').click();}
  function importReportFile(file){if(!file||!canImport())return;var reason=pendingImportReason;if(reason.length<8){toast('Import cancelled: an audit reason is required.','error');return;}var reader=new FileReader();reader.onload=function(){var content=String(reader.result||'');var added=0;if(file.name.toLowerCase().endsWith('.csv')){var rows=parseCsv(content);if(!rows.length){toast('No report rows found in that CSV.','error');return;}rows.forEach(function(row){var lower={};Object.keys(row).forEach(function(k){lower[k.toLowerCase().trim().replace(/[\s-]+/g,'_')]=row[k];});var text=lower.text||lower.report||lower.description||lower.update||'';if(!text.trim())return;var date=lower.report_date||lower.date||todayISO();var externalId=lower.report_id||lower.id||'';var reportId=externalId||nextReportId();if(state.reports.some(function(existing){return existing.id===reportId;}))reportId=nextReportId();var meta={id:reportId,externalId:externalId,date:date,discipline:lower.discipline||detectDiscipline(text),reporter:lower.reporter||lower.supervisor||'Imported report',actualStart:lower.actual_start||lower.actual_start_date||'',actualEnd:lower.actual_end||lower.actual_finish||lower.actual_end_date||'',progress:lower.progress||lower.percent_complete||'',activityId:lower.activity_id||lower.activityid||''};addReportFromText(text,meta.discipline,date,file.name,'spreadsheet',meta);added++;});}else if(content.trim()){addReportFromText(content.trim(),detectDiscipline(content),todayISO(),file.name,'text');added++;}pendingImportReason='';if(!added){toast('No usable report text found in that file.','error');return;}save(reason).then(function(ok){if(ok)toast(added+' report'+(added===1?'':'s')+' added by '+authUser.name+' and recorded in the audit trail.');});render();};reader.onerror=function(){toast('Could not read that file.','error');};reader.readAsText(file);}
  function parseCsv(text){var rows=[],row=[],cell='',quoted=false;for(var i=0;i<text.length;i++){var c=text[i],n=text[i+1];if(c==='"'){if(quoted&&n==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&n==='\n')i++;row.push(cell);cell='';if(row.some(function(v){return String(v).trim()!=='';}))rows.push(row);row=[];}else cell+=c;}if(cell!==''||row.length){row.push(cell);rows.push(row);}if(rows.length<2)return[];var headers=rows.shift().map(function(h){return h.trim().replace(/^\uFEFF/,'');});return rows.map(function(values){var obj={};headers.forEach(function(h,i){obj[h]=String(values[i]||'').trim();});return obj;}).filter(function(obj){return Object.values(obj).some(function(v){return v!=='';});});}

  function importScheduleFile(file){if(!file||!canRole())return;var reason=pendingScheduleReason;if(reason.length<8){toast('Schedule import cancelled: an audit reason is required.','error');return;}var reader=new FileReader();reader.onload=function(){var rows=parseCsv(String(reader.result||''));if(!rows.length){toast('No schedule rows found. Check the CSV headers.','error');return;}var added=0,updated=0;rows.forEach(function(raw){var row={};Object.keys(raw).forEach(function(k){row[k.toLowerCase().trim().replace(/[\s-]+/g,'_')]=raw[k];});var id=row.activity_id||row.id||row.code;if(!id)return;var found=currentActivity(id);var importedProgress=row.percent_complete||row.progress;var obj={id:id,wbs:row.wbs||'',name:row.activity_name||row.name||row.activity||'',discipline:row.discipline||'Unassigned',location:row.location||'',plannedStart:row.planned_start||row.planned_start_date||row.start_date||'',plannedFinish:row.planned_finish||row.planned_finish_date||row.finish_date||'',actualStart:row.actual_start||'',actualFinish:row.actual_finish||row.actual_end||'',actualStartTime:row.actual_start_time||'',actualFinishTime:row.actual_finish_time||row.actual_end_time||'',predecessors:(row.predecessors||'').split(/[;,|]/).map(function(v){return v.trim();}).filter(Boolean),contractor:row.contractor||'',updateCadenceHours:Number(row.update_cadence_hours||48),progress:Number(importedProgress||0),plannedProgress:Number(row.planned_progress||row.planned_percent_complete||0),owner:row.owner||row.responsible||'—',status:row.status||'Not started'};if(!obj.name||!obj.plannedFinish)return;if(found){if(!row.actual_start)obj.actualStart=found.actualStart;if(!row.actual_finish&&!row.actual_end)obj.actualFinish=found.actualFinish;if(!row.actual_start_time)obj.actualStartTime=found.actualStartTime||'';if(!row.actual_finish_time&&!row.actual_end_time)obj.actualFinishTime=found.actualFinishTime||'';if(!row.predecessors)obj.predecessors=found.predecessors||[];if(!row.contractor)obj.contractor=found.contractor||'';if(!row.update_cadence_hours)obj.updateCadenceHours=found.updateCadenceHours||48;if(!importedProgress)obj.progress=found.progress;if(!row.status)obj.status=found.status;Object.assign(found,obj);updated++;}else{state.activities.push(obj);added++;}});pendingScheduleReason='';save(reason).then(function(ok){if(ok)toast('Schedule import recorded: '+added+' added, '+updated+' updated.');});render();};reader.onerror=function(){toast('Could not read schedule file.','error');};reader.readAsText(file);}
