  function exportCsv(rows,filename){var csv=rows.map(function(row){return row.map(function(v){var s=String(v===null||v===undefined?'':v);return'"'+s.replace(/"/g,'""')+'"';}).join(',');}).join('\r\n');downloadText(filename,'\uFEFF'+csv,'text/csv;charset=utf-8');}
  function exportUpdates(){var rows=[['report_id','report_date','discipline','report_text','source','reporter','activity_id','actual_start','actual_finish','progress','status','reviewer','planner_note','created_by','created_by_role','created_at_utc','is_default_sample','archived']];state.reports.forEach(function(r){rows.push([r.id,r.date,r.discipline,r.text,r.source,r.reporter,r.activityId,r.actualStart,r.actualEnd,r.progress,r.status,r.reviewer||'',r.note||'',r.createdBy||'',r.createdByRole||'',r.createdAt||'',!!r.isDefault,!!r.archived]);});exportCsv(rows,'sitelink_progress_updates.csv');toast('Progress records exported as CSV.');}
  function exportSchedule(){var rows=[['activity_id','wbs','activity_name','discipline','location','planned_start','planned_finish','actual_start','actual_finish','actual_start_time','actual_finish_time','percent_complete','planned_progress','owner','contractor','predecessors','update_cadence_hours','status']];state.activities.forEach(function(a){rows.push([a.id,a.wbs,a.name,a.discipline,a.location,a.plannedStart,a.plannedFinish,a.actualStart,a.actualFinish,a.actualStartTime||'',a.actualFinishTime||'',a.progress,a.plannedProgress,a.owner,a.contractor||'',(a.predecessors||[]).join(';'),a.updateCadenceHours||48,statusForActivity(a)]);});exportCsv(rows,'sitelink_activity_register.csv');toast('Activity register exported as CSV.');}
  function exportAudit(){var rows=[['time_utc','actor','role','action','record_id','source_location','reason','what_changed']];state.audit.forEach(function(a){rows.push([a.time,a.actor,a.role,a.action,a.record,a.where,a.why,a.what]);});exportCsv(rows,'sitelink_audit_trail.csv');toast('Audit history exported as CSV.');}
  function downloadText(name,text,type){var blob=new Blob([text],{type:type||'text/plain'});var url=URL.createObjectURL(blob);var a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url);},1000);}
  function openExportModal(){var modal='<div class="modal-backdrop" id="modalBackdrop"><section class="modal-card" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><header class="modal-header"><div><h2 id="modalTitle">Export project data</h2><p>Download spreadsheet-friendly CSV files for the records you can access.</p></div><button class="modal-close" data-close-modal aria-label="Close">×</button></header><div class="modal-body"><div class="file-choice"><button class="file-tile" id="exportActivityOption"><div class="tile-icon">▤</div><strong>Activity register</strong><small>Planned dates, actual dates, progress, discipline, and owner.</small></button><button class="file-tile" id="exportReportOption"><div class="tile-icon">⇥</div><strong>Progress reports</strong><small>Source text, match, review status, dates, and planner note.</small></button></div><div style="margin-top:11px"><button class="file-tile" id="exportAuditOption" style="width:100%"><div class="tile-icon">◷</div><strong>Audit trail</strong><small>Who, role, time, source, reason, and change summary.</small></button></div><div class="notice-box" style="margin-top:13px">Exports are copies for review. They do not connect or write back to Primavera, MS Project, or an external PMIS.</div></div><footer class="modal-footer"><span class="field-hint">Files are created on your device.</span><button class="button button-secondary" data-close-modal>Close</button></footer></section></div>';document.getElementById('modalRoot').innerHTML=modal;document.querySelectorAll('[data-close-modal]').forEach(function(b){b.addEventListener('click',closeModal);});document.getElementById('modalBackdrop').addEventListener('click',function(e){if(e.target.id==='modalBackdrop')closeModal();});document.getElementById('exportActivityOption').addEventListener('click',function(){exportSchedule();closeModal();});document.getElementById('exportReportOption').addEventListener('click',function(){exportUpdates();closeModal();});document.getElementById('exportAuditOption').addEventListener('click',function(){exportAudit();closeModal();});}
  function openHelpModal(){var modal='<div class="modal-backdrop" id="modalBackdrop"><section class="modal-card" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><header class="modal-header"><div><h2 id="modalTitle">About this prototype</h2><p>SIH26122 · field-to-schedule progress bridge</p></div><button class="modal-close" data-close-modal aria-label="Close">×</button></header><div class="modal-body"><div class="memory-callout" style="margin:0"><span>◉</span><div><strong>Secure sign-in and review history</strong><p>Accounts are stored on the server with hashed passwords. Each role is checked by the server. Adding, reviewing, archiving, and access changes require a reason that appears with actor, time, source, and change details in the audit trail.</p></div></div><div class="divider-label">PROTOTYPE LIMITS</div><div class="cause-list"><div class="cause-row"><i class="cause-bullet"></i>Matching uses terminology-aware local heuristics; scores are not calibrated probabilities. Optional LLM assists extraction only.</div><div class="cause-row"><i class="cause-bullet"></i>OCR uses Tesseract. Optional LLM assistance is server-configured with source-quote validation and a local fallback. MS Project XML uses a labeled adapter; no live PMIS connection exists.</div><div class="cause-row"><i class="cause-bullet"></i>SQLite records are stored in the server data folder; back it up before moving the app.</div><div class="cause-row"><i class="cause-bullet"></i>All preloaded project reports and activities are synthetic examples.</div></div><div class="divider-label">ROLE SUMMARY</div><div class="source-note">Admin: manage accounts and remove/restore reports. Planner: import schedules and review updates. Supervisor: add reports but cannot approve or remove them. Viewer: read-only access.</div></div><footer class="modal-footer"><span class="field-hint">First-run administrator account is created at sign-in setup.</span><button class="button button-secondary" data-close-modal>Close</button></footer></section></div>';document.getElementById('modalRoot').innerHTML=modal;document.querySelectorAll('[data-close-modal]').forEach(function(b){b.addEventListener('click',closeModal);});document.getElementById('modalBackdrop').addEventListener('click',function(e){if(e.target.id==='modalBackdrop')closeModal();});}
  function renderAgentAnalysis(data){var f=data.facts||{},cand=data.candidates||[];var candidateHtml=cand.map(function(c){var a=currentActivity(c.activity_id);if(!a)return'';var checked=Number(c.score)>=.70?' checked':'';return'<label class="candidate-option"><input type="radio" name="agentCandidate" value="'+esc(a.id)+'"'+checked+'><span><strong>'+esc(a.id)+' · '+esc(a.name)+'</strong><small>'+esc(a.discipline)+' · '+esc(a.location)+' · '+esc((c.reasons||[]).join('; '))+'</small></span><span class="candidate-confidence '+scoreClass(Number(c.score)||0)+'">'+scoreLabel(Number(c.score)||0)+' heuristic</span></label>';}).join('');var factRows=[['Discipline',f.discipline||'Unassigned'],['Event',f.eventStatus||'Not stated'],['Actual start',f.actualStart||'Not stated'],['Start time',f.startTime||'Not stated'],['Actual finish',f.actualEnd||'Not stated'],['Finish time',f.endTime||'Not stated'],['Progress',f.progress===null||f.progress===undefined?'Not stated':f.progress+'%'],['Reported blocker',f.blocker||'None stated']].map(function(x){return'<div class="fact-chip"><small>'+esc(x[0])+'</small><strong>'+esc(x[1])+'</strong></div>';}).join('');var evidence=(data.evidence||[]).map(function(e){return'<div class="evidence-row"><span>✓</span><div><strong>'+esc(e.label||e.field||e.kind)+'</strong><small>'+esc(e.value||'')+(e.quote?' · “'+esc(e.quote)+'”':'')+'</small></div></div>';}).join('');var questions=[];if(f.startTime&&!f.actualStart)questions.push('Which date did this clock time occur on? The text gives a time but no event date.');if(f.eventStatus==='started'&&!f.actualStart)questions.push('What calendar date did the activity actually start?');if(f.eventStatus==='complete'&&!f.actualEnd)questions.push('What calendar date did the activity actually finish?');if(f.progress===null||f.progress===undefined)questions.push('If known, what percentage was complete at the time of this report?');var clarification=questions.length?'<div class="clarification-box"><strong>Clarification to confirm</strong><ul>'+questions.map(function(q){return'<li>'+esc(q)+'</li>';}).join('')+'</ul><small>Leave unknown facts blank. You can still save the source as unmatched or pending review.</small></div>':'';var top=cand[0];var suggested=top&&Number(top.score)>=.70?top.activity_id:'';var notice=suggested?'<div class="notice-box">Top candidate: '+esc(suggested)+' · '+Math.round(Number(top.score)*100)+'% heuristic ranking. Confirm or choose another. This is not an auto-link.</div>':'<div class="data-warning">No match meets the 70% suggestion threshold. Keep it unmatched or create a schedule activity for Planner review.</div>';return'<div class="agent-analysis"><div class="agent-analysis-title"><strong>Extracted execution facts</strong><span class="role-badge">'+esc(data.provider||'Local rules')+'</span></div><div class="fact-grid">'+factRows+'</div>'+clarification+'<div class="divider-label">RANKED SCHEDULE CANDIDATES</div>'+notice+'<div class="candidate-select">'+(candidateHtml||'<div class="empty-state">No activities in the schedule.</div>')+'</div><div class="divider-label">SOURCE EVIDENCE</div><div class="evidence-list">'+(evidence||'<div class="source-note">No explicit facts were extracted. The original text remains available for planner review.</div>')+'</div><div class="field agent-reason"><label for="agentReason">Why are you adding this report? (required)</label><textarea id="agentReason" class="textarea" placeholder="For example: End-of-shift piping progress update."></textarea></div><div class="agent-result-actions">'+(canRole()?'<button class="small-button" data-agent-action="create">＋ Create new schedule activity</button>':'')+'<button class="button button-secondary" data-agent-action="save-unmatched">Save unmatched to inbox</button><button class="button button-primary" data-agent-action="save">Save as pending report</button></div><div class="source-note">The Planner must confirm any schedule change. Extraction and match evidence are rechecked by the server when saved.</div></div>';}
  function analyzeAgentUpdate(){if(!canImport()){toast('Sign in as Supervisor, Planner, or Admin to analyze an update.','error');return;}var text=(document.getElementById('agentText').value||'').trim();if(!text){toast('Enter a site update first.','error');return;}var button=document.querySelector('[data-agent-action="analyze"]');if(button){button.disabled=true;button.textContent='Analyzing…';}var draft={text:text,date:document.getElementById('agentDate').value||todayISO(),discipline:document.getElementById('agentDiscipline').value||'',sourceType:agentCaptureType,source:agentCaptureType==='voice'?'AI Time Agent · browser dictation':'AI Time Agent · typed'};apiRequest('/api/analyze','POST',Object.assign(draft,{projectId:activeProjectId})).then(function(data){lastAgentDraft=Object.assign(draft,{analysis:data});document.getElementById('agentResult').innerHTML=renderAgentAnalysis(data);}).catch(function(error){toast(error.message,'error');}).finally(function(){var current=document.querySelector('[data-agent-action="analyze"]');if(current){current.disabled=false;current.textContent='Analyze update';}});}
  function saveAgentUpdate(forceUnmatched){if(!canImport()||!lastAgentDraft){toast('Analyze a report before saving it.','error');return;}var reason=(document.getElementById('agentReason')||{}).value||'';reason=reason.trim();if(reason.length<8){toast('Add a reason of at least 8 characters.','error');return;}var checked=document.querySelector('input[name="agentCandidate"]:checked');var chosen=forceUnmatched?'':(checked?checked.value:'');var facts=lastAgentDraft.analysis.facts||{};var report={id:nextReportId(),date:lastAgentDraft.date,discipline:facts.discipline||lastAgentDraft.discipline||'Unassigned',text:lastAgentDraft.text,reporter:authUser.name,source:lastAgentDraft.source,sourceType:lastAgentDraft.sourceType,actualStart:facts.actualStart||'',actualEnd:facts.actualEnd||'',actualStartTime:facts.startTime||'',actualEndTime:facts.endTime||'',progress:facts.progress===null||facts.progress===undefined?'':facts.progress,status:chosen?'pending':'unmatched',activityId:'',suggestedActivityId:chosen,confidence:lastAgentDraft.analysis.confidence||0,matchReason:lastAgentDraft.analysis.match_reason||[],evidence:lastAgentDraft.analysis.evidence||[],extraction:facts,createdAt:new Date().toISOString(),note:chosen?'Suggested link '+chosen+'; Planner approval required.':'No schedule link selected; retain for Planner triage.'};state.reports.unshift(report);currentView='inbox';render();save(reason).then(function(ok){if(ok)toast(chosen?'Saved as pending. Planner review is required before schedule updates.':'Saved as unmatched for Planner triage.');});}
  function openCreateActivityFromAgent(){if(!canRole()||!lastAgentDraft){toast('Only a Planner or Admin can create schedule activities.','error');return;}var f=lastAgentDraft.analysis.facts||{};var modal='<div class="modal-backdrop" id="modalBackdrop"><section class="modal-card" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><header class="modal-header"><div><h2 id="modalTitle">Create schedule activity</h2><p>Unmatched field work becomes a proposed node; the source report remains pending.</p></div><button class="modal-close" data-close-modal aria-label="Close">×</button></header><div class="modal-body"><div class="form-grid"><div class="field"><label for="newActivityId">Activity ID</label><input class="input" id="newActivityId" placeholder="e.g. PIP-L6-099"></div><div class="field"><label for="newActivityDiscipline">Discipline</label><input class="input" id="newActivityDiscipline" value="'+esc(f.discipline||lastAgentDraft.discipline||'Unassigned')+'"></div><div class="field full"><label for="newActivityName">Activity name</label><input class="input" id="newActivityName" value="'+esc(lastAgentDraft.text.slice(0,120))+'"></div><div class="field"><label for="newActivityLocation">Location</label><input class="input" id="newActivityLocation" placeholder="If known"></div><div class="field"><label for="newActivityOwner">Owner</label><input class="input" id="newActivityOwner" placeholder="If known"></div><div class="field"><label for="newActivityStart">Planned start</label><input class="input" type="date" id="newActivityStart"></div><div class="field"><label for="newActivityFinish">Planned finish</label><input class="input" type="date" id="newActivityFinish"></div><div class="field full"><label for="newActivityReason">Why is this activity being added? (required)</label><textarea class="textarea" id="newActivityReason" placeholder="Planner reason for adding this schedule node"></textarea></div></div><div class="notice-box" style="margin-top:12px">This creates the schedule node and saves the source report for review. It does not approve progress or mark work complete.</div></div><footer class="modal-footer"><span class="field-hint">Planner / Admin only · action is audited</span><div><button class="button button-secondary" data-close-modal>Cancel</button> <button class="button button-primary" id="saveNewActivity">Create and keep report pending</button></div></footer></section></div>';document.getElementById('modalRoot').innerHTML=modal;document.querySelectorAll('[data-close-modal]').forEach(function(b){b.addEventListener('click',closeModal);});document.getElementById('modalBackdrop').addEventListener('click',function(e){if(e.target.id==='modalBackdrop')closeModal();});document.getElementById('saveNewActivity').addEventListener('click',saveNewActivityFromAgent);}
  function saveNewActivityFromAgent(){var id=document.getElementById('newActivityId').value.trim().toUpperCase(),name=document.getElementById('newActivityName').value.trim(),reason=document.getElementById('newActivityReason').value.trim(),start=document.getElementById('newActivityStart').value,finish=document.getElementById('newActivityFinish').value;if(!id||!name||!start||!finish||reason.length<8){toast('Activity ID, name, planned start, planned finish, and a reason of at least 8 characters are required.','error');return;}if(currentActivity(id)){toast('That activity ID already exists.','error');return;}if(start&&finish&&finish<start){toast('Planned finish cannot be earlier than start.','error');return;}var activity={id:id,wbs:'',name:name,discipline:document.getElementById('newActivityDiscipline').value.trim()||'Unassigned',location:document.getElementById('newActivityLocation').value.trim(),plannedStart:start,plannedFinish:finish,actualStart:'',actualFinish:'',actualStartTime:'',actualFinishTime:'',progress:0,plannedProgress:0,owner:document.getElementById('newActivityOwner').value.trim()||'—',contractor:'',predecessors:[],updateCadenceHours:48,status:'Not started'};state.activities.push(activity);var facts=lastAgentDraft.analysis.facts||{};var report={id:nextReportId(),date:lastAgentDraft.date,discipline:facts.discipline||activity.discipline,text:lastAgentDraft.text,reporter:authUser.name,source:lastAgentDraft.source,sourceType:lastAgentDraft.sourceType,actualStart:facts.actualStart||'',actualEnd:facts.actualEnd||'',actualStartTime:facts.startTime||'',actualEndTime:facts.endTime||'',progress:facts.progress===null||facts.progress===undefined?'':facts.progress,status:'pending',activityId:'',suggestedActivityId:'',createdAt:new Date().toISOString(),note:'New schedule activity proposed from unmatched field report; Planner approval still required.'};state.reports.unshift(report);currentView='inbox';render();save(reason).then(function(ok){if(ok)toast('Schedule activity created and source report kept pending.');});}
  function askExecutionMemory(){var input=document.getElementById('memoryQuestion'),question=(input&&input.value||'').trim();if(!question){toast('Enter a question for execution memory.','error');return;}apiRequest('/api/memory','POST',{question:question,projectId:activeProjectId}).then(function(result){var target=document.getElementById('memoryAnswer');if(target){target.textContent=result.answer;var ids=(result.records||[]).map(function(row){return row.id||row.activity_id;}).filter(Boolean);var small=document.createElement('small');small.textContent=(result.sample_count||0)+' stored record(s) · '+(result.basis||'Project execution memory')+(ids.length?' · '+ids.slice(0,8).join(', '):'');target.appendChild(small);}}).catch(function(error){toast(error.message,'error');});}
  var activeRecognition=null;
  function toggleAgentVoice(){var Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){toast('Speech recognition is unavailable in this browser. Type the update instead.','error');return;}if(activeRecognition){activeRecognition.stop();activeRecognition=null;return;}var button=document.getElementById('agentVoiceButton');activeRecognition=new Speech();activeRecognition.lang='en-IN';activeRecognition.interimResults=false;activeRecognition.onstart=function(){if(button)button.textContent='Listening… click to stop';};activeRecognition.onresult=function(event){var transcript=event.results&&event.results[0]&&event.results[0][0]?event.results[0][0].transcript:'';if(transcript){var input=document.getElementById('agentText');input.value=(input.value?input.value+' ':'')+transcript;agentCaptureType='voice';}};activeRecognition.onerror=function(){toast('Voice input did not finish. Check the transcript or type the report.','error');};activeRecognition.onend=function(){activeRecognition=null;if(button)button.textContent='◉ Dictate update';};try{activeRecognition.start();}catch(error){activeRecognition=null;toast('Could not start browser dictation. Type the update instead.','error');}}
