  document.addEventListener('click',function(e){var action=e.target.closest('[data-agent-action]');if(action){var kind=action.getAttribute('data-agent-action');if(kind==='analyze')analyzeAgentUpdate();else if(kind==='save')saveAgentUpdate(false);else if(kind==='save-unmatched')saveAgentUpdate(true);else if(kind==='create')openCreateActivityFromAgent();else if(kind==='memory')askExecutionMemory();return;}if(e.target.closest('#agentVoiceButton')){toggleAgentVoice();return;}var missing=e.target.closest('[data-missing-log]');if(missing){if(!canImport()){toast('Supervisor, Planner, or Admin access is required to log an update.','error');return;}var activity=currentActivity(missing.getAttribute('data-missing-log'));navigate('agent');var text=document.getElementById('agentText');if(text)text.value=(activity?activity.id+' — '+activity.name+'. ':'')+'Please provide the current site progress, actual event date/time, and any blocker.';agentCaptureType='text';}});
