  renderOverview=function(){var approved=state.reports.filter(function(report){return !report.archived&&report.status==='approved';}),valid=approved.filter(function(report){return report.progress!==''&&report.progress!==null&&report.progress!==undefined&&Number.isFinite(Number(report.progress));}),average=valid.length?Math.round(valid.reduce(function(sum,report){return sum+Number(report.progress);},0)/valid.length):null,now=todayISO(),openToday=state.activities.filter(function(activity){return activity.plannedStart&&activity.plannedFinish&&activity.plannedStart<=now&&activity.plannedFinish>=now&&Number(activity.progress)<100;}),overdue=state.activities.filter(function(activity){return activity.plannedFinish&&activity.plannedFinish<now&&Number(activity.progress)<100;}),waiting=pendingReports(),conflicts=(state.intelligence&&state.intelligence.conflicts||[]).filter(function(item){return item.unresolved;}),missing=(state.intelligence&&state.intelligence.missing_updates||[]),fingerprints=(state.intelligence&&state.intelligence.fingerprints)||[],recent=state.reports.filter(function(report){return !report.archived;}).slice().sort(function(a,b){return String(b.createdAt||b.date||'').localeCompare(String(a.createdAt||a.date||''));}).slice(0,5),attention=[{label:'Reports waiting for review',count:waiting.length,view:'inbox'},{label:'Overdue activities',count:overdue.length,view:'schedule'},{label:'Unresolved report conflicts',count:conflicts.length,view:'conflicts'},{label:'Activities missing an update',count:missing.length,view:'missing'}];var todayRows=openToday.slice(0,5).map(function(activity){return'<div class="home-work-row"><div><strong>'+esc(activity.id)+' · '+esc(activity.name)+'</strong><small>'+esc(activity.discipline||'Unassigned')+' · '+Number(activity.progress||0)+'% in the register</small></div><button class="table-link" data-activity="'+esc(activity.id)+'">Details</button><button class="table-link" data-missing-log="'+esc(activity.id)+'">Log update</button></div>';}).join('');var attentionRows=attention.map(function(item){return'<button class="home-attention-row" data-nav="'+item.view+'"><span>'+esc(item.label)+'</span><strong class="'+(item.count?'attention-count':'')+'">'+item.count+'</strong></button>';}).join('');return'<div class="kpi-grid">'+kpiCard('Approved progress',average===null?'—':average+'%',valid.length+' reviewed source record'+(valid.length===1?'':'s'),'✓','green',average===null?'No approved values yet':'Review-backed')+kpiCard('Needs a decision',waiting.length,'Pending or unmatched reports','⇥','amber',waiting.length?'Open review queue':'Queue clear')+kpiCard('Today’s open work',openToday.length,'Activities in their planned window','◷','blue','Schedule dates')+kpiCard('Execution history',fingerprints.length,'Complete approved activity records','◈','','Historical only')+'</div><div class="home-priority-grid"><section class="panel"><div class="panel-header"><div class="panel-heading"><h2>Today’s work</h2><p>'+esc(fmtDate(now,true))+' · open activities within their planned date window</p></div><button class="panel-action" data-nav="schedule">Open register ↗</button></div><div class="panel-body"><div class="home-work-list">'+(todayRows||'<div class="empty-state"><strong>No open activity is scheduled for today</strong>Schedule dates and approved actuals determine this list.</div>')+'</div></div></section><section class="panel"><div class="panel-header"><div class="panel-heading"><h2>Needs attention</h2><p>Live counts from the current project records</p></div></div><div class="panel-body"><div class="home-attention-list">'+attentionRows+'</div><p class="home-record-note">Counts come from project-scoped reports, schedule dates, conflicts, and update cadence records.</p></div></section></div><div class="home-secondary-grid"><section class="panel"><div class="panel-header"><div class="panel-heading"><h2>Forecast &amp; milestone exposure</h2><p>Schedule and history calculations are labeled separately from predictions.</p></div><button class="panel-action" data-nav="execution">Open analysis ↗</button></div><div class="panel-body"><div class="home-forecast"><span class="home-forecast-icon">↗</span><div><strong>Review the schedule forecast</strong><p>CPM dates use schedule durations and dependencies. Historical estimates require reviewed execution records. Each view shows its source records and data limits.</p><small>'+fingerprints.length+' complete execution-history record'+(fingerprints.length===1?'':'s')+' available as historical evidence</small></div></div></div></section><section class="panel home-ask-panel"><div class="panel-header"><div class="panel-heading"><h2>Ask SiteLink</h2><p>Questions use this project’s stored, reviewed execution records.</p></div></div><div class="panel-body"><div class="memory-question"><input class="input" id="memoryQuestion" placeholder="Ask about approved blockers, durations, or activity history"><button class="button button-primary" data-agent-action="memory">Ask</button></div><div id="memoryAnswer" class="memory-answer">Answers include their evidence basis. Missing information remains unknown; it is not guessed.<small>Project-scoped execution memory</small></div></div></section></div><section class="panel" style="margin-top:14px"><div class="panel-header"><div class="panel-heading"><h2>Latest source reports</h2><p>Every submitted source stays in the searchable review history.</p></div><button class="panel-action" data-nav="inbox">Open inbox ↗</button></div>'+renderRecentTable(recent)+'</section>';};

